class Solution:
    def asteroidCollision(self, asteroids: list[int]) -> list[int]:
        stack = []
        # collision:
        # a -> <- b ==> a > 0 and b < 0
        # case abs(a) > abs(b): b is destroyed => nothing
        # case abs(a) < abs(b): a is destroyed => pop out of the stack
        # non-collision:
        # a <- <- b or a -> -> b ==> a * b > 0
        # a <- -> b ==> a < 0 and b > 0
        # only a, no b ==> empty stack

        for a in asteroids:
            if a > 0:
                stack.append(a)
            else:
                while stack and stack[-1] > 0 and abs(a) > stack[-1]:
                    stack.pop()
                if stack and stack[-1] == abs(a):
                    stack.pop()
                elif not stack or stack[-1] < 0:
                    stack.append(a)

        return stack
